  readonly migrate?: (raw: unknown) => unknown;
}

/** Stamps both the emit clock and the branch onto a persisted document, each only when missing. */
const stampClockAndBranch = (raw: unknown): unknown =>
  stampWhenMissing('branch', PRE_W207_BRANCH)(stampWhenMissing('generatedAt', PRE_W206_GENERATED_AT)(raw));

const REGISTERED = {
  requirements: { kind: 'requirements', schema: RequirementsDocSchema, fileName: 'requirements.json' },
  resolution: { kind: 'resolution', schema: ResolutionIrSchema, fileName: 'resolution.json', migrate: stampClockAndBranch },
  goals: { kind: 'goals', schema: GoalsDocSchema, fileName: 'goals.json' },
  flowMap: { kind: 'flowMap', schema: FlowMapIrSchema, fileName: 'flow-map.json', migrate: stampClockAndBranch },
  clarifyQuestions: { kind: 'clarifyQuestions', schema: ClarifyQuestionsSchema, fileName: 'questions.json' },
  residue: { kind: 'residue', schema: ResidueDocSchema, fileName: 'residue.json' },
  plan: { kind: 'plan', schema: PlanIrSchema, fileName: 'plan.json', migrate: stampWhenMissing('branch', PRE_W207_BRANCH) },
  quickstart: { kind: 'quickstart', schema: QuickstartIrSchema, fileName: 'quickstart.json' },
  placement: { kind: 'placement', schema: PlacementDocSchema, fileName: 'placement.json' },
  planAudit: { kind: 'planAudit', schema: PlanAuditDocSchema, fileName: 'plan-audit.json' },
  research: { kind: 'research', schema: ResearchDocSchema, fileName: 'research.json' },
  realityProbe: { kind: 'realityProbe', schema: RealityProbeDocSchema, fileName: 'reality-probe.json' },
  tasks: { kind: 'tasks', schema: TaskIrSchema, fileName: 'tasks.json', migrate: migrateTaskIr },
  gateFindings: { kind: 'gateFindings', schema: GateFindingsDocumentSchema, fileName: 'findings.json' },
} satisfies Record<IrKind, IrSpec>;

/** Every registered IR kind and its spec: schema, artifact file name, optional pre-schema migrate. */
export const IR_KINDS: Readonly<Record<IrKind, IrSpec>> = REGISTERED;

type Registered = typeof REGISTERED;

/** The parsed document of a kind. */
export type IrOf<K extends IrKind> = Readonly<z.output<Registered[K]['schema']>>;

